from __future__ import annotations
from pathlib import Path
from typing import List
from pydantic import AliasChoices, Field, SecretStr, field_validator
from pydantic_settings import BaseSettings, SettingsConfigDict

class Settings(BaseSettings):
    model_config = SettingsConfigDict(env_file=".env", env_file_encoding="utf-8", case_sensitive=False, extra="ignore", frozen=True)

    brand_name: str = "Underdog PSP"
    api_version: str = "v1"

    scylla_hosts: List[str] = Field(default_factory=lambda: ["scylla-host:9042"], validation_alias=AliasChoices("SCYLLA_HOSTS"))
    scylla_keyspace: str = Field(default="payment_keyspace", validation_alias=AliasChoices("SCYLLA_KEYSPACE"))
    redis_url: str = Field(default="redis://localhost:6379/0", validation_alias=AliasChoices("REDIS_URL"))
    kdb_host: str = Field(default="localhost", validation_alias=AliasChoices("KDB_HOST"))
    kdb_port: int = Field(default=5000, validation_alias=AliasChoices("KDB_PORT"))

    keycloak_url: str = Field(default="", validation_alias=AliasChoices("KEYCLOAK_URL"))
    keycloak_client_id: str = Field(default="psp-client", validation_alias=AliasChoices("KEYCLOAK_CLIENT_ID"))
    keycloak_client_secret: SecretStr = Field(validation_alias=AliasChoices("KEYCLOAK_CLIENT_SECRET"))
    jwt_secret: SecretStr = Field(validation_alias=AliasChoices("JWT_SECRET"))

    erstegroup_api_url: str = Field(default="", validation_alias=AliasChoices("ERSTEGROUP_API_URL", "ERSTE_API_URL"))
    erstegroup_client_id: str = Field(validation_alias=AliasChoices("ERSTEGROUP_CLIENT_ID", "ERSTE_CLIENT_ID", "ERTSE_CLIENT_ID"))
    erstegroup_client_secret: SecretStr = Field(validation_alias=AliasChoices("ERSTEGROUP_CLIENT_SECRET", "ERSTE_CLIENT_SECRET", "ERTSE_CLIENT_SECRET"))
    erstegroup_cert_path: Path = Field(validation_alias=AliasChoices("ERSTEGROUP_CERT_PATH", "ERSTE_CERT_PATH", "ERTSE_CERT_PATH"))
    erstegroup_private_key_path: Path = Field(validation_alias=AliasChoices("ERSTEGROUP_PRIVATE_KEY_PATH", "ERSTE_PRIVATE_KEY_PATH", "ERTSE_PRIVATE_KEY_PATH"))

    kafka_bootstrap_servers: List[str] = Field(default_factory=lambda: ["localhost:9092"], validation_alias=AliasChoices("KAFKA_BOOTSTRAP_SERVERS"))
    kafka_topic_users: str = Field(default="user-events", validation_alias=AliasChoices("KAFKA_TOPIC_USERS"))
    kafka_topic_fraud: str = Field(default="fraud-alerts", validation_alias=AliasChoices("KAFKA_TOPIC_FRAUD"))

    modal_secret: SecretStr = Field(validation_alias=AliasChoices("MODAL_SECRET"))

    apple_pay_merchant_id: str = Field(validation_alias=AliasChoices("APPLE_PAY_MERCHANT_ID"))
    apple_pay_shared_secret: SecretStr = Field(validation_alias=AliasChoices("APPLE_PAY_SHARED_SECRET"))

    sentry_dsn: str = Field(default="", validation_alias=AliasChoices("SENTRY_DSN"))
    prometheus_port: int = Field(default=8001, validation_alias=AliasChoices("PROMETHEUS_PORT"))

    default_currency: str = Field(default="EUR", validation_alias=AliasChoices("DEFAULT_CURRENCY"))

    @field_validator("scylla_hosts", "kafka_bootstrap_servers", mode="before")
    @classmethod
    def _parse_list(cls, v):
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return []
            if s.startswith("["):
                try:
                    import json
                    loaded = json.loads(s)
                    if isinstance(loaded, list):
                        return [str(x).strip() for x in loaded if str(x).strip()]
                except Exception:
                    pass
            return [x.strip() for x in s.split(",") if x.strip()]
        return v

    @field_validator("kdb_port", "prometheus_port")
    @classmethod
    def _validate_port(cls, v):
        port = int(v)
        if not 1 <= port <= 65535:
            raise ValueError("port must be between 1 and 65535")
        return port

    @field_validator("erstegroup_cert_path", "erstegroup_private_key_path", mode="before")
    @classmethod
    def _coerce_path(cls, v):
        return v if isinstance(v, Path) else Path(str(v))

    @field_validator("default_currency")
    @classmethod
    def _currency_iso3(cls, v):
        code = str(v).upper()
        if len(code) != 3 or not code.isalpha():
            raise ValueError("default_currency must be a 3-letter ISO code")
        return code

settings = Settings()
